// Aplana los campos personalizados de Kommo a algo legible.
const crudo = $input.first().json ?? {};
const l = crudo.data ?? crudo;
const campos = {};
for (const c of (l.custom_fields_values ?? [])) {
  const v = (c.values ?? [])[0] ?? {};
  let valor = v.value ?? v.enum_id ?? null;
  // Un campo de fecha vaciado se queda en 0, porque Kommo no acepta null ahi
  // (ver armar_reinicio.js). Sin esta linea, 0 viaja como si fuera una fecha
  // y acaba siendo el 1 de enero de 1970 en una cotizacion.
  if (c.field_type === 'date' && Number(valor) === 0) valor = null;
  campos[c.field_name] = valor;
}
const msg = $('formatear').first().json;
const rafaga = $('leer_rafaga').first().json;
return [{ json: {
  lead_id: String(l.id ?? msg.lead_id),
  etapa_id: l.status_id ?? null,
  responsable_id: l.responsible_user_id ?? null,
  presupuesto: l.price ?? 0,
  campos,
  // Todo lo que el cliente dijo en la rafaga, ya junto en un solo texto.
  chats: rafaga.chats ?? msg.texto,
  cuantos_mensajes: Number(rafaga.cuantos ?? 1),
  origen: msg.origen,
  autor: msg.autor,
  adjunto_tipo: msg.adjunto_tipo,
  adjunto_url: msg.adjunto_url,
}}];

// Convierte lo que entendio el Director en el PATCH de campos de Kommo.
//
// Solo el Director escribe en Kommo. Si cada agente parchara el mismo lead se
// pisarian entre ellos y no habria forma de saber quien puso que.
//
// Regla de oro: solo se escribe lo que el cliente DIJO. Un campo que el
// Director no pudo determinar se queda como esta. Sobrescribir con null
// borraria lo que una encargada capturo a mano.

const CAMPO = {
  salon: 352870,
  tipo_evento: 352872,
  fecha_evento: 352874,
  invitados: 352876,
};

// Los select de Kommo guardan enum_id, no texto.
const ENUM_SALON = {
  norma: 281622, esmeralda: 281624, santacruz: 281626, quetzal: 281628,
};
const ENUM_TIPO = {
  xv: 281630, boda: 281632, graduacion: 281634,
  posada: 281636, cumpleanos: 281638, babyshower: 281640,
};

// Del JSON del Director, aunque venga envuelto en cercos de codigo.
let salida = $json.output ?? '';
if (typeof salida === 'string') {
  salida = salida.trim().replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '').trim();
  try { salida = JSON.parse(salida); } catch (e) { salida = {}; }
}
const datos = (salida && salida.datos) || {};

const valores = [];
const anotado = {};

if (ENUM_SALON[datos.salon]) {
  valores.push({ field_id: CAMPO.salon, values: [{ enum_id: ENUM_SALON[datos.salon] }] });
  anotado.salon = datos.salon;
}
if (ENUM_TIPO[datos.tipo_evento]) {
  valores.push({ field_id: CAMPO.tipo_evento, values: [{ enum_id: ENUM_TIPO[datos.tipo_evento] }] });
  anotado.tipo_evento = datos.tipo_evento;
}
// El modelo inventa el dia cuando el cliente solo dijo el mes: «diciembre de
// 2027» salio como 2027-12-01 y se escribio en Kommo. Por eso, ademas del
// formato, se exige que el numero del dia aparezca en lo que el cliente
// escribio. Si el dia venia arrastrado de un mensaje anterior, ese mensaje ya
// lo escribio en su turno, asi que no se pierde nada.
function dijoElDia(fecha, texto) {
  const dia = Number(fecha.slice(8, 10));
  const t = String(texto ?? '');
  if (new RegExp('(^|[^0-9])0?' + dia + '([^0-9]|$)').test(t)) return true;
  return dia === 1 && /\bprimero\b/i.test(t);
}

if (/^\d{4}-\d{2}-\d{2}$/.test(datos.fecha_evento ?? '')
    && dijoElDia(datos.fecha_evento, $('formatLead').first().json.chats)) {
  // Kommo guarda las fechas como epoch. Se usa mediodia UTC a proposito: a
  // las 00:00 UTC en Monterrey (UTC-6) todavia es el dia anterior, y la
  // fecha del evento aparecería corrida un dia.
  const epoch = Math.floor(Date.parse(datos.fecha_evento + 'T12:00:00Z') / 1000);
  valores.push({ field_id: CAMPO.fecha_evento, values: [{ value: epoch }] });
  anotado.fecha_evento = datos.fecha_evento;
}
// ─────────────────────────────────────────────────────────────────────────
// La fecha, ya con su dia de la semana, lista para que el agente la nombre.
//
// El Lic. quiere que nunca se diga «el 20 de marzo» a secas, sino «el sabado
// 20 de marzo». Pero esto NO se le puede pedir al prompt: sacar el dia de la
// semana de una fecha es aritmetica, y el modelo la falla sin avisar. Peor
// aun, la falla con seguridad — diria «viernes 20 de marzo» con el mismo tono
// con que dice el precio, y el cliente le cree.
//
// Asi que se calcula aqui y se le entrega hecha. El modelo solo la copia.
// Con acentos: esto lo copia el agente tal cual y sale al chat del cliente.
const DIA = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const MES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
             'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

// En español la fecha va «20 de marzo de 2027». «Marzo 20 de 2027» es orden
// de ingles y en el chat se nota raro.
function enLetras(iso) {
  const y = Number(iso.slice(0, 4)), m = Number(iso.slice(5, 7)), d = Number(iso.slice(8, 10));
  const dow = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  return `${DIA[dow]} ${d} de ${MES[m - 1]} de ${y}`;
}

// Primero la de este mensaje; si en este turno no dijo fecha, la que ya traia
// el lead. Sin esto, en cuanto el cliente escribe «¿y cuanto sale?» el agente
// se queda sin el dia de la semana y vuelve a decir la fecha pelada.
let fechaISO = anotado.fecha_evento ?? null;
if (!fechaISO) {
  const epoch = Number($('formatLead').first().json.campos?.['Fecha del evento']);
  // Se guarda a mediodia UTC justamente para que el dia no se corra al pasarla
  // a texto. Ver el comentario de arriba.
  if (Number.isFinite(epoch) && epoch > 0) {
    fechaISO = new Date(epoch * 1000).toISOString().slice(0, 10);
  }
}

const invitados = Number(datos.invitados);
if (Number.isFinite(invitados) && invitados > 0) {
  valores.push({ field_id: CAMPO.invitados, values: [{ value: invitados }] });
  anotado.invitados = invitados;
}

// El interruptor ya no se escribe desde aqui. Cuando el campo se llamaba «IA
// activa» habia que marcarlo en el primer contacto, porque Kommo omite los
// checkbox sin marcar y sin marcarlo no se podia distinguir «nadie lo ha
// tocado» de «la encargada lo apago».
//
// Ahora se llama «Stop IA» y la ausencia significa lo correcto por si sola:
// sin marcar, la IA corre. Marcarlo seria justo lo contrario de lo que se
// quiere en un lead nuevo.

return [{
  json: {
    hay_datos: valores.length > 0,
    lead_id: $('formatLead').first().json.lead_id,
    anotado,
    fecha_iso: fechaISO,
    fecha_larga: fechaISO ? enLetras(fechaISO) : null,
    // La linea ya armada, lista para pegarla al turno del agente.
    //
    // Se arma aqui y no en la expresion del nodo a proposito: un ternario con
    // concatenacion dentro de {{ }} le reventó al agente con «invalid syntax»
    // y, como nadie le escribio al bot en todo un dia, el fallo no aparecio
    // hasta la primera conversacion real. En el nodo queda una sola
    // referencia a una propiedad, que no tiene como romperse.
    nota_fecha: fechaISO
      ? `

[Sistema] La fecha de la que se habla es el ${enLetras(fechaISO)}. `
        + 'Nombrala siempre asi, con su dia de la semana.'
      : '',
    cuerpo: { custom_fields_values: valores },
  },
}];

// Parte la respuesta del agente en las piezas que espera enviar_mensaje_salones.
//
// Se hace con codigo y no con otro agente a proposito: partir en frontera de
// parrafo es una regla, no un juicio. Un modelo haciendo esto cuesta, tarda, y
// algun dia devuelve algo distinto para el mismo texto.
const bruto = $json.output ?? '';
let texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);

// El modelo a veces envuelve la respuesta en cercos de codigo o en un JSON.
texto = texto.trim().replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '').trim();
if (texto.startsWith('{')) {
  try {
    const o = JSON.parse(texto);
    texto = o.respuesta ?? o.parte1 ?? o.output ?? texto;
  } catch (e) { /* no era JSON: se queda con el texto tal cual */ }
}

const MAX_PARTES = 2;   // por ahora dos; el subflujo admite hasta cuatro

// Se corta por ritmo de WhatsApp, no por longitud: la informacion en un
// mensaje y la pregunta de cierre en otro. Antes se cortaba a los 600
// caracteres, pero una cotizacion tipica ronda los 400 — con esa regla el
// corte en dos casi nunca se activaba.
//
// Nunca se corta a media frase: si no hay frontera de parrafo, va entera. Un
// mensaje largo de una sola pieza molesta menos que uno partido a la mitad.
function partir(t) {
  const parrafos = t.split(/\n\s*\n/).map((x) => x.trim()).filter(Boolean);
  if (parrafos.length < 2) return [t];
  // El ultimo parrafo se va solo: en las respuestas de Maya es la invitacion
  // a visitar o la pregunta. Lo anterior se junta en el primer mensaje.
  return [parrafos.slice(0, -1).join('\n\n'), parrafos[parrafos.length - 1]]
    .slice(0, MAX_PARTES);
}

const partes = partir(texto);
const fl = $('formatLead').first().json;


return [{
  json: {
    cuantas_partes: partes.length,
    parte1: partes[0] ?? '',
    parte2: partes[1] ?? '',
    parte3: '',
    parte4: '',
    lead_id: fl.lead_id,
    // La pone elegir_lamina, el nodo siguiente: aqui no se puede leer la
    // salida de `cotizar` porque un Code no alcanza a un nodo-herramienta.
    imagen_url: '',
    mensaje_cliente: fl.chats,
    // Declarados en el subflujo pero sin usar en su codigo: van en cero para
    // no mover ninguna etapa por accidente.
    proximo_paso: 0,
    status_id: 0,
    // Que agente redacto. Se guarda aqui porque despues de este nodo
    // $prevNode.name ya seria 'formatear_respuesta'.
    agente: $prevNode.name,
    texto_completo: texto,
  },
}];

// Decide qué lámina acompaña a la respuesta, y la pega al resto del envío.
//
// Esto NO lo hace el modelo. Si tuviera que copiar una URL de 80 caracteres,
// tarde o temprano se le cae uno — y una URL rota no da error: el mensaje sale
// sin foto y la ejecución queda en verde.
//
// Tampoco se lee de `cotizar`, aunque sea quien ya trae la lámina: un nodo
// Code no puede alcanzar un nodo conectado como herramienta. Por eso el
// catálogo entero llega por el camino principal, desde /api/imagenes, y el
// cruce se hace aquí.

const limpiar = (s) => String(s ?? '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '');
const sinEventos = (s) => limpiar(s).replace(/\s*eventos\s*$/, '').trim();

const resp = $('formatear_respuesta').first().json;
const fl = $('formatLead').first().json;

// Todos los salones, tengan lámina o no: reconocer el nombre de uno que aún
// no tiene foto es justo lo que evita mandarle la de otro.
const salonesTodos = ($json.salones ?? [])
  .map((s) => sinEventos(s.nombre || s.clave)).filter(Boolean);

// Una entrada por paquete y salón; dentro, sus láminas. Un paquete puede
// tener varias: el de «Baby Shower, Despedidas de Soltera y Bautizos» se
// cotiza igual para los tres, pero el arte lo parte en tres.
const grupos = new Map();
for (const l of ($json.laminas ?? [])) {
  const clave = l.paquete + '|' + l.salon;
  if (!grupos.has(clave)) {
    grupos.set(clave, {
      salon_texto: sinEventos(l.salon_nombre || l.salon),
      paquete_texto: limpiar(l.paquete).replace(/^paquete\s+/, '').trim(),
      imagenes: [],
    });
  }
  grupos.get(clave).imagenes.push({ etiqueta: l.etiqueta, url: l.url });
}

// Las fotos de cortesia, por salon. Cada una trae sus pistas: como la nombra
// el cliente, que no es como la nombra el catalogo —nadie escribe «arreglos de
// mesa en prestamo», escriben «centros de mesa»—.
const cortesias = ($json.cortesias ?? []).map((c) => ({
  salon_texto: sinEventos(c.salon_nombre || c.salon),
  url: c.url,
  pistas: String(c.pistas ?? c.titulo ?? '').split(',')
    .map((x) => limpiar(x).trim()).filter(Boolean),
}));

// De qué salón se está hablando. Se exige saberlo SIEMPRE, aunque solo un
// salón tuviera imágenes cargadas: si el agente cotiza Santa Cruz y todavía no
// se subió su lámina, quedarse con la de Norma le manda al cliente la foto de
// otro salón. Preferible sin foto.
//
// `cerca` son las posiciones contra las que se desempata cuando el texto
// nombra varios salones: gana el que esté más pegado. En «Norma está ocupado,
// pero en Santa Cruz el Paquete Plata...» el salón de la oferta es el de al
// lado, no el primero que aparece.
function salonDe(t, cerca = []) {
  const nombrados = [...new Set(salonesTodos)]
    .filter((x) => x && t.includes(x))
    .map((x) => ({
      salon: x,
      dist: cerca.length ? Math.min(...cerca.map((p) => Math.abs(p - t.indexOf(x)))) : 0,
    }))
    .sort((a, b) => a.dist - b.dist);

  if (nombrados.length === 1) return nombrados[0].salon;
  if (nombrados.length > 1) {
    if (nombrados[0].dist === nombrados[1].dist) return null;
    return nombrados[0].salon;
  }
  // No lo nombró. El del lead sirve: lo escribió el Director cuando el cliente
  // lo dijo.
  return sinEventos(fl.campos?.['Salón']) || null;
}

function elegir() {
  const t = limpiar(resp.texto_completo);
  if (!t) return '';

  // 1. Los paquetes que el agente nombró en el mensaje que va a salir.
  const paquetesEnTexto = [...new Set([...grupos.values()]
    .map((g) => g.paquete_texto).filter((x) => x && t.includes(x)))]
    .map((x) => t.indexOf(x));
  if (!paquetesEnTexto.length) return '';

  const salon = salonDe(t, paquetesEnTexto);
  if (!salon) return '';

  // 2. De ese salón, el paquete que Maya nombró.
  const candidatos = [...grupos.values()].filter(
    (g) => g.salon_texto === salon && g.paquete_texto && t.includes(g.paquete_texto));

  // Ante cualquier duda, sin imagen. La lámina equivocada el cliente la lee
  // como la oferta.
  if (candidatos.length !== 1) return '';
  const imgs = candidatos[0].imagenes;
  if (imgs.length === 1) return imgs[0].url;

  // Varias láminas del mismo paquete: cuál toca lo dice el cliente, no el
  // paquete. A quien va a bautizar no se le mandan globos de despedida.
  const dicho = limpiar(fl.chats);
  // El arte parte dos paquetes en varias laminas: «Baby Shower, Despedidas de
  // Soltera y Bautizos» en tres, y «Aniversarios / Cumpleanos» en dos. El
  // precio y el contenido son los mismos; lo que cambia es a quien se le
  // enseña, asi que lo decide lo que escribio el cliente.
  const PISTA = {
    bautizo:     /bautiz/,
    despedida:   /despedida/,
    babyshower:  /baby ?shower/,
    aniversario: /aniversario|bodas? de (plata|oro|plomo)/,
    cumpleanos:  /cumplea|cumple /,
  };
  for (const img of imgs) {
    const re = PISTA[img.etiqueta];
    if (re && re.test(dicho)) return img.url;
  }
  return '';
}

// Cuando se cotiza manda SIEMPRE la lamina del paquete. Es la unica regla que
// importa de las dos: el agente nombra las cortesias dentro de la propia
// cotizacion —«incluye el Espejo de Bienvenida, el Aro iluminado...»—, asi que
// sin esta prioridad una cotizacion acabaria mandando la foto de una cortesia
// en lugar de la hoja del paquete, que es la que trae el precio.
//
// La foto de una cortesia es para el otro momento: cuando el cliente pregunta
// por una cosa concreta y no se esta cotizando. Ahi la foto vale mas que
// cualquier descripcion.
function elegirCortesia() {
  const dicho = limpiar(fl.chats);
  if (!dicho) return '';

  const salon = salonDe(limpiar(resp.texto_completo));
  if (!salon) return '';

  // Tiene que haberla preguntado EL CLIENTE. Buscarla en lo que escribio el
  // agente daria falsos positivos todo el tiempo, porque las enumera al cotizar.
  const encajan = cortesias.filter((c) => c.salon_texto === salon
    && c.pistas.some((pi) => dicho.includes(pi)));

  // Preguntó por dos: no se adivina cual queria ver.
  const distintas = new Set(encajan.map((c) => c.url));
  return distintas.size === 1 ? [...distintas][0] : '';
}

let url = '';
try { url = elegir() || elegirCortesia(); } catch (e) { url = ''; }

// Se devuelve todo lo que armó formatear_respuesta, con la imagen puesta: así
// los nodos que siguen leen de un solo sitio.
return [{ json: { ...resp, imagen_url: url } }];

// Lo que hay que hacer en Kommo cuando alguien manda «/*».
//
// Borrar la memoria sola no alcanza: el Director lee los campos del lead y
// arrastra la fecha y el salon de la conversacion anterior, asi que el
// «empezamos de cero» era mentira a medias.
//
// Pero esto borra datos de verdad, y ya paso en otro cliente: un «/*» cayo en
// un lead que resulto ser una clienta real y le limpio los campos en plena
// cotizacion. Por eso ANTES de borrar se deja una nota en el lead con lo que
// habia. Si alguna vez vuelve a pasar, el dato se recupera leyendo la nota en
// vez de reconstruirlo preguntandole al cliente.

const CAMPO = {
  salon: 352870,
  tipo_evento: 352872,
  fecha_evento: 352874,
  invitados: 352876,
  paquete: 352880,
};

// Lo que NO se toca, a proposito:
//   352882 «Stop IA»        — si la encargada apago la IA, un /* no la puede
//                             volver a encender. Seria lo contrario de lo que
//                             quiso quien la apago.
//   352884 «Estado de contacto» — es operativo del equipo, no del agente.

const lead = $('formatLead').first().json;
const campos = lead.campos ?? {};

// El nombre que Kommo le da a cada campo, para leer lo que habia. Se mira por
// nombre porque es lo que trae `formatLead`, ya aplanado.
const NOMBRE = {
  'Salón': 'Salón',
  'Tipo de evento': 'Tipo de evento',
  'Fecha del evento': 'Fecha del evento',
  'Invitados': 'Invitados',
  'Paquete cotizado': 'Paquete cotizado',
};

const comoTexto = (nombre, valor) => {
  if (valor === null || valor === undefined || valor === '') return null;
  // La fecha viene en epoch y una nota con «1797055200» no le sirve a nadie.
  if (nombre === 'Fecha del evento') {
    const n = Number(valor);
    if (Number.isFinite(n) && n > 0) return new Date(n * 1000).toISOString().slice(0, 10);
  }
  return String(valor);
};

const habia = [];
for (const nombre of Object.keys(NOMBRE)) {
  const t = comoTexto(nombre, campos[nombre]);
  if (t !== null) habia.push(`${nombre}: ${t}`);
}

const nota = habia.length
  ? 'Se reinició la conversación con «/*». Los campos quedaron en blanco. '
    + 'Lo que había antes:\n' + habia.join('\n')
  : 'Se reinició la conversación con «/*». El lead no tenía datos capturados.';

// Vaciar un campo en Kommo depende del TIPO, y no esta documentado junto:
//
//   `values: []`            -> rechazado siempre. «TooFew: exactly 1 element»
//   `{ value: null }`       -> funciona en texto, numero y select
//   `{ value: null }` en fecha -> rechazado. «NotNullable» + «InvalidDateFormat»
//   `{ value: 0 }` en fecha -> aceptado, y es lo unico que acepta
//
// El 0 deja la fecha en el 1-ene-1970 en vez de vacia. Es feo en la ficha de
// Kommo, pero `formatLead` lo traduce a null y nada aguas abajo lo ve como
// una fecha de verdad. Probado contra la cuenta, campo por campo.
const FECHA = CAMPO.fecha_evento;
const cuerpo = {
  custom_fields_values: Object.values(CAMPO).map((field_id) => ({
    field_id,
    values: [{ value: field_id === FECHA ? 0 : null }],
  })),
};

return [{
  json: {
    lead_id: lead.lead_id,
    tenia_datos: habia.length > 0,
    nota,
    cuerpo,
  },
}];

// La linea «[Sistema]» que acompaña al mensaje del cliente.
//
// Junta dos cosas que el agente no puede deducir y que necesita ANTES de
// cotizar: el dia de la semana de la fecha, y si ese dia tiene algo que
// avisar.
//
// Lo de Semana Santa vivia solo dentro de `cotizar`, asi que mientras el
// agente seguia recabando invitados la fecha pasaba sin que nadie dijera
// nada. El cliente decia «27 de marzo», ella confirmaba tan tranquila, y el
// aviso llegaba dos mensajes despues o no llegaba.

const p = $('armar_patch').first().json;

// La consulta al panel va en «continuar aunque falle»: si el panel no
// contesta, se pierde el aviso de la fecha especial pero la conversacion
// sigue. Quedarse mudo seria peor que no avisar.
let especial = null;
try {
  const r = $input.first().json ?? {};
  especial = r.fecha_especial ?? null;
} catch (e) { especial = null; }

const partes = [];
if (p.fecha_larga) {
  partes.push(`La fecha de la que se habla es el ${p.fecha_larga}. `
    + 'Nombrala siempre asi, con su dia de la semana.');
}
if (especial && especial.aviso) {
  partes.push(`Ese dia es ${especial.titulo}. ${especial.aviso} `
    + (especial.se_puede_cotizar
      ? 'Diselo con tus palabras en cuanto hablen de esa fecha, sin esperar a cotizar, '
        + 'y sigue adelante con normalidad: la fecha se vende igual.'
      : 'Esa fecha NO se puede vender.'));
}

return [{
  json: {
    // Todo lo de armar_patch sigue viaje: `hay_datos` y `guardar_en_kommo`
    // leen de aqui.
    ...p,
    fecha_especial: especial,
    nota_fecha: partes.length ? '\n\n[Sistema] ' + partes.join(' ') : '',
  },
}];
